static int mandel(float c_re, float c_im, int count) {
    float z_re = c_re, z_im = c_im;
    int i;
    for (i = 0; i < count; ++i) {
        if (z_re * z_re + z_im * z_im > 4.f)
            break;

        float new_re = z_re * z_re - z_im * z_im;
        float new_im = 2.f * z_re * z_im;
        z_re = c_re + new_re;
        z_im = c_im + new_im;
    }

    return i;
}

void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[]) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    for (int j = 0; j < height; j++) {
        for (int i = 0; i < width; ++i) {
            float x = x0 + i * dx;
            float y = y0 + j * dy;

            int index = (j * width + i);
            output[index] = mandel(x, y, maxIterations);
        }
    }
}

#if defined(__SSE__)
#include <xmmintrin.h>

struct SimdGroup {
    __m128 c_re;
    __m128 c_im;
    __m128 z_re;
    __m128 z_im;
    __m128 counts;
    __m128 active;
};

static inline int advance_group(SimdGroup &g, __m128 one, __m128 two, __m128 four) {
    __m128 magnitude = _mm_add_ps(_mm_mul_ps(g.z_re, g.z_re), _mm_mul_ps(g.z_im, g.z_im));
    __m128 escaped = _mm_cmpgt_ps(magnitude, four);
    g.active = _mm_andnot_ps(escaped, g.active);

    int active_lanes = _mm_movemask_ps(g.active);
    if (active_lanes == 0)
        return 0;

    g.counts = _mm_add_ps(g.counts, _mm_and_ps(g.active, one));

    __m128 re_squared = _mm_mul_ps(g.z_re, g.z_re);
    __m128 im_squared = _mm_mul_ps(g.z_im, g.z_im);
    __m128 next_re = _mm_add_ps(g.c_re, _mm_sub_ps(re_squared, im_squared));
    __m128 next_im = _mm_add_ps(g.c_im, _mm_mul_ps(_mm_mul_ps(two, g.z_re), g.z_im));

    g.z_re = _mm_or_ps(_mm_and_ps(g.active, next_re), _mm_andnot_ps(g.active, g.z_re));
    g.z_im = _mm_or_ps(_mm_and_ps(g.active, next_im), _mm_andnot_ps(g.active, g.z_im));
    return active_lanes;
}

static inline void store_group_counts(const SimdGroup &g, int output[], int index) {
    float counts[4];
    _mm_storeu_ps(counts, g.counts);
    output[index + 0] = static_cast<int>(counts[0]);
    output[index + 1] = static_cast<int>(counts[1]);
    output[index + 2] = static_cast<int>(counts[2]);
    output[index + 3] = static_cast<int>(counts[3]);
}
#endif

static void mandelbrot_simd(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[]) {
#if defined(__SSE__)
    // Float lane counters are exact up to 2^24. Larger iteration limits use
    // the scalar path so every valid int count remains exact.
    if (maxIterations >= 0 && maxIterations <= 16777216) {
        float dx = (x1 - x0) / width;
        float dy = (y1 - y0) / height;
        const __m128 zero = _mm_setzero_ps();
        const __m128 one = _mm_set1_ps(1.f);
        const __m128 two = _mm_set1_ps(2.f);
        const __m128 four = _mm_set1_ps(4.f);
        const __m128 all = _mm_castsi128_ps(_mm_set1_epi32(-1));

        for (int j = 0; j < height; ++j) {
            float y = y0 + j * dy;
            int i = 0;

            // Four independent four-pixel recurrences form each 16-pixel block.
            for (; width - i >= 16; i += 16) {
                SimdGroup g0, g1, g2, g3;
                g0.c_re = _mm_setr_ps(x0 + (i + 0) * dx, x0 + (i + 1) * dx, x0 + (i + 2) * dx, x0 + (i + 3) * dx);
                g1.c_re = _mm_setr_ps(x0 + (i + 4) * dx, x0 + (i + 5) * dx, x0 + (i + 6) * dx, x0 + (i + 7) * dx);
                g2.c_re = _mm_setr_ps(x0 + (i + 8) * dx, x0 + (i + 9) * dx, x0 + (i + 10) * dx, x0 + (i + 11) * dx);
                g3.c_re = _mm_setr_ps(x0 + (i + 12) * dx, x0 + (i + 13) * dx, x0 + (i + 14) * dx, x0 + (i + 15) * dx);
                g0.c_im = g1.c_im = g2.c_im = g3.c_im = _mm_set1_ps(y);
                g0.z_re = g0.c_re; g1.z_re = g1.c_re; g2.z_re = g2.c_re; g3.z_re = g3.c_re;
                g0.z_im = g1.z_im = g2.z_im = g3.z_im = _mm_set1_ps(y);
                g0.counts = g1.counts = g2.counts = g3.counts = zero;
                g0.active = g1.active = g2.active = g3.active = all;

                int a0 = 15, a1 = 15, a2 = 15, a3 = 15;
                for (int iter = 0; iter < maxIterations && (a0 | a1 | a2 | a3) != 0; ++iter) {
                    a0 = advance_group(g0, one, two, four);
                    a1 = advance_group(g1, one, two, four);
                    a2 = advance_group(g2, one, two, four);
                    a3 = advance_group(g3, one, two, four);
                }

                int index = j * width + i;
                store_group_counts(g0, output, index + 0);
                store_group_counts(g1, output, index + 4);
                store_group_counts(g2, output, index + 8);
                store_group_counts(g3, output, index + 12);
            }

            for (; i < width; ++i) {
                float x = x0 + i * dx;
                output[j * width + i] = mandel(x, y, maxIterations);
            }
        }
        return;
    }
#endif

    mandelbrot_serial(x0, y0, x1, y1, width, height, maxIterations, output);
}

extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
    (void)input2;
    (void)threads;
    const float *a = static_cast<const float *>(input1);
    mandelbrot_simd(a[0], a[1], a[2], a[3], n * 3 / 2, n, parameter, static_cast<int *>(output));
}
